    schedule_keys = {"start_day", "end_day"}
    budget_keys = {"monthly_budget", "coupon", "departments"}
    legal_keys = {"accept_terms"}
    step_sets = [account_keys, plan_keys, schedule_keys, budget_keys, legal_keys]
