    blocked = []
    for i, (name, keys) in enumerate(zip(STEPS, step_sets), 1):
        ok = not any(k in errors for k in keys)
        completion[name] = ok
        if not ok:
            blocked.append(i)
    current = max(1, min(5, int(state.get("current_step", 1))))
