    approved_count = 0
    dept_total = 0
    for dept in state["departments"]:
        dept["name"] = _norm_text(dept.get("name", "")) or "Department"
        dept["allocation"] = int(dept.get("allocation", 0))
        dept["approved"] = bool(dept.get("approved", False))
