    warnings = {}

    allowed_regions = {
        "US": ["us", "na"],
        "CA": ["na"],
        "EU": ["eu"],
        "GB": ["eu", "uk"],
    }.get(country, ["us", "eu", "na"])

    required = ["org_name", "email", "password", "confirm", "plan", "country", "region", "age"]
