    }
    state = {
        "fields": fields,
        "current_step": 1,
        "departments": [],
        "next_dept_id": 1,
        "new_dept_name": "Ops",
        "new_dept_allocation": 0,
        "errors": {},
        "warnings": {},
        "required_fields": [],
        "visible_fields": [],
        "allowed_regions": [],
        "completion_by_step": {},
        "blocked_steps": [],
        "next_step_enabled": False,
        "price": {},
        "error_summary": [],
        "can_submit": False,
    }
