    elif t == "set_bool":
        name = action["field"]
        value = bool(action["value"])
        if name in BOOL_FIELDS:
            state["input_" + name] = value
            state["fields"][name] = value
    elif t == "add_department":
        name = _norm_text(action.get("name", state.get("new_dept_name", "Department"))) or "Department"
